package dev.zomboid.clans;
import java.util.*;import java.util.function.Consumer;
public final class Effects {
 static final Map<String,Object> sounds=new HashMap<>();static final String[] NAMES={"generator","nexus_hit","phase","victory","defeat","deposit","withdraw","start"};
 public static void register(Object event,Object registry){for(String name:NAMES){Object id=Rewards.loc("factionfriction:"+name),sound=R.call(R.type("net.minecraft.sounds.SoundEvent"),"createVariableRangeEvent",id);sounds.put(name,sound);R.call(event,"register",registry,(Consumer<Object>)helper->R.call(helper,"register",id,sound));}}
 static void personal(Object player,String name){Object sound=sounds.get(name);if(sound!=null)R.call(player,"playNotifySound",sound,R.get(R.type("net.minecraft.sounds.SoundSource"),"MASTER"),.85f,1f);}
 static void announce(Pve.Wave w,String name){Object server=R.call(w.level,"getServer");for(UUID id:w.participants){Object p=Clans.online(server,id);if(p!=null)personal(p,name);}}
 static void hud(Pve.Wave w,int damage,String result){Object server=R.call(w.level,"getServer"),m=Clans.manager(server);int max=Nexus.maxHealth(Clans.state(m).profile(w.clan));for(UUID id:w.participants){Object p=Clans.online(server,id);if(p!=null)R.call(R.type("me.danialisntcool.factionfriction.network.FFNetwork"),"sendToPlayer",p,new ClanPacket(11,Math.max(0,w.health)+"|"+max+"|"+damage+"|"+w.stage+"|"+result,"",0));}}
 static void tick(Pve.Wave w){long now=Clans.now(R.call(w.level,"getServer"));int damage=Math.max(0,w.displayHealth-w.health);w.displayHealth=w.health;if(damage>0)announce(w,"nexus_hit");hud(w,damage,"");if(sounds.isEmpty())return;Object pos=Nexus.pos(Clans.state(Clans.manager(R.call(w.level,"getServer"))).profile(w.clan));double x=R.coord(pos,"X")+.5,y=R.coord(pos,"Y")+1.1,z=R.coord(pos,"Z")+.5;Object types=R.type("net.minecraft.core.particles.ParticleTypes");R.call(w.level,"sendParticles",R.get(types,"SMOKE"),x,y,z,5,.22,.1,.22,.025);R.call(w.level,"sendParticles",R.get(types,"ELECTRIC_SPARK"),x,y-.1,z,3,.4,.2,.4,.05);if(now>=w.nextHum){w.nextHum=now+60;R.call(w.level,"playSound",null,pos,sounds.get("generator"),R.get(R.type("net.minecraft.sounds.SoundSource"),"BLOCKS"),1.6f,1f);}}
 static void finish(Pve.Wave w,boolean success){announce(w,success?"victory":"defeat");hud(w,Math.max(0,w.displayHealth-w.health),success?"VICTORIA":"DERROTA");}
}
